import React, { useEffect, useState, useRef } from "react";
import { Navbar, Nav, Container } from "react-bootstrap";

export default function ResponsiveNavbar() {
  const [activeId, setActiveId] = useState("hero");
  const observerRef = useRef(null);

  useEffect(() => {
    const ids = [
      "hero",
      "albums",
      "shows",
      "videos",
      "bio",
      "buy",
      "featured",
      "contact",
    ];
    const sections = ids
      .map((id) => document.getElementById(id))
      .filter(Boolean);

    if (sections.length === 0) return undefined;

    // Use IntersectionObserver to pick the section with largest intersection ratio
    const obs = new IntersectionObserver(
      (entries) => {
        // pick the entry with highest intersectionRatio that's intersecting
        const visible = entries.filter((e) => e.isIntersecting);
        if (visible.length > 0) {
          visible.sort((a, b) => b.intersectionRatio - a.intersectionRatio);
          setActiveId(visible[0].target.id);
        }
      },
      {
        root: null,
        rootMargin: "-40% 0px -40% 0px",
        threshold: [0, 0.25, 0.5, 0.75, 1],
      }
    );

    sections.forEach((el) => obs.observe(el));
    observerRef.current = obs;

    // If the page loads with a hash, respect it immediately
    const hash = window.location.hash && window.location.hash.replace("#", "");
    if (hash && ids.includes(hash)) setActiveId(hash);

    return () => {
      if (observerRef.current) observerRef.current.disconnect();
    };
  }, []);

  return (
    <Navbar bg="light" expand="lg" className="fixed-top">
      <Container>
        <Navbar.Brand href="/">
          <img
            src="img/core-img/logo.png"
            alt="One Music"
            style={{ height: 32 }}
            className="img-fluid"
            loading="lazy"
          />
        </Navbar.Brand>
        <Navbar.Toggle aria-controls="main-navbar" />
        <Navbar.Collapse id="main-navbar">
          <Nav className="me-auto">
            <Nav.Link href="#hero" active={activeId === "hero"}>
              Home
            </Nav.Link>
            <Nav.Link href="#albums" active={activeId === "albums"}>
              Albums
            </Nav.Link>
            <Nav.Link href="#shows" active={activeId === "shows"}>
              Shows
            </Nav.Link>
            <Nav.Link href="#videos" active={activeId === "videos"}>
              Videos
            </Nav.Link>
            <Nav.Link href="#bio" active={activeId === "bio"}>
              Bio
            </Nav.Link>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
}
